export class RecentlyViewed{static#t="viewedProducts";static addProduct(t){let e=this.getProducts();e=e.filter(e=>e!==t),e.unshift(t),localStorage.setItem(this.#t,JSON.stringify(e))}static clearProducts(){localStorage.removeItem(this.#t)}static getProducts(){return JSON.parse(localStorage.getItem(this.#t)||"[]")}}